{"kind":"tool","id":"fO6RP8mIB-g","toolName":"write_file","input":{"path":"resources/bridge/qio-bridge.ps1","instructions":"Windows integration bridge: emits JSONL media/volume/brightness/battery events on stdout and reads JSONL commands on stdin.","content":"<#
  Qio Windows bridge.

  A single long-lived PowerShell 5.1 process that watches Windows and talks to the
  Qio main process over stdio:

    stdout : one JSON object per line, { "type": "...", ... } events
    stdin  : one JSON object per line, { "cmd": "...", "id": n, ... } commands

  Everything here uses API that ships with Windows (WinRT projection, Core Audio
  COM interop, WMI, user32) so Qio needs no native Node modules and no build tools.
#>

[CmdletBinding()]
param(
  [int]$MediaIntervalMs = 250,
  [int]$SlowIntervalMs = 1000,
  [int]$VerySlowIntervalMs = 5000,
  [switch]$Once
)

$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

# ---------------------------------------------------------------- stdout bus --
$script:Emit = {
  param([hashtable]$Payload)
  try {
    [Console]::Out.WriteLine(($Payload | ConvertTo-Json -Compress -Depth 6))
    [Console]::Out.Flush()
  } catch { }
}

function Send-Event {
  param([string]$Type, [hashtable]$Data)
  $payload = @{ type = $Type }
  if ($Data) { foreach ($k in $Data.Keys) { $payload[$k] = $Data[$k] } }
  & $script:Emit $payload
}

# ------------------------------------------------------------- WinRT helper --
$script:Await = $null
try {
  Add-Type -AssemblyName [… 11,951 characters omitted] | Out-Null }
            '^brightness-set' {
              try {
                $methods = Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightnessMethods -ErrorAction SilentlyContinue
                foreach ($m in $methods) { Invoke-CimMethod -InputObject $m -MethodName WmiSetBrightness -Arguments @{ Timeout = 1; Brightness = [byte]$cmd.level } | Out-Null }
              } catch { }
            }
            '^ping' { Send-Event 'pong' @{ id = $cmd.id } }
            '^quit' { $stop = $true }
          }
        } catch {
          Send-Event 'bridge-log' @{ level = 'error'; message = "command $($cmd.cmd) failed: $($_.Exception.Message)" }
        }
      }
    }
  }

  # --- media -----------------------------------------------------------------
  $media = Get-MediaSnapshot
  if (Compare-Media $media $script:LastMedia) {
    if ($media) { Send-Event 'media' $media } else { Send-Event 'media' @{ status = 'unavailable' } }
    $script:LastMedia = $media
  }

  # --- volume / brightness / battery ----------------------------------------
  $native = Get-NativeSnapshot
  if ($native.volume -ne $script:LastVolume -or $native.muted -ne $script:LastMuted) {
    Send-Event 'volume' @{ volume = $native.volume; muted = $native.muted }
    $script:LastVolume = $native.volume
    $script:LastMuted = $native.muted
  }
  if ($native.brightness -ne $null -and $native.brightness -ne $script:LastBrightness) {
    Send-Event 'brightness' @{ brightness = $native.brightness }
    $script:LastBrightness = $native.brightness
  }
  if ($native.capsLock -ne $script:LastCaps) {
    Send-Event 'capslock' @{ capsLock = $native.capsLock }
    $script:LastCaps = $native.capsLock
  }
  if ($native.layout -and $native.layout -ne $script:LastLayout) {
    if ($script:LastLayout) { Send-Event 'layout' @{ layout = $native.layout } }
    $script:LastLayout = $native.layout
  }
  if ($native.battery -ne $null -and ($native.battery -ne $script:LastBattery -or $native.charging -ne $script:LastCharging)) {
    Send-Event 'power' @{ battery = $native.battery; charging = $native.charging }
    $script:LastBattery = $native.battery
    $script:LastCharging = $native.charging
  }

  $script:SlowTick++
  if ($Once) { $stop = $true; continue }
  Start-Sleep -Milliseconds $MediaIntervalMs
}

Send-Event 'bye' @{}
"}}


